create table wksp_dtesc.sgt_sitios_enlace_wan (
    id             number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    sitio_id       number,
    enlace_wan_id  number,
    seq            number,
    creado_por     varchar2(255 char),
    creado_el      timestamp(6),
    modificado_por varchar2(255 char),
    modificado_el  timestamp(6)
);

alter table wksp_dtesc.sgt_sitios_enlace_wan
    add constraint sgt_sitios_enlace_wan_id_pk primary key ( id )
        using index enable;


